// Regenerates src/client.generated.ts from src/client.ts.
// tests/client.test.ts fails while the generated file is stale.
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const entry = fileURLToPath(new URL("../src/client.ts", import.meta.url));
const output = fileURLToPath(
  new URL("../src/client.generated.ts", import.meta.url),
);

export async function buildClientSource(): Promise<string> {
  const built = await Bun.build({
    entrypoints: [entry],
    format: "iife",
    target: "browser",
    minify: true,
  });
  if (!built.success)
    throw new Error(built.logs.map((log) => log.message).join("\n"));
  const file = built.outputs[0];
  if (!file) throw new Error("Bun.build produced no output.");
  const script = await file.text();
  return format(
    `// Generated by scripts/build-client.ts from src/client.ts. Do not edit.\nexport default ${JSON.stringify(script.trim())};\n`,
  );
}

// Written already formatted, so `bun fmt` leaves the file as generated.
async function format(source: string): Promise<string> {
  const proc = Bun.spawn(["bun", "fmt", "--stdin-filepath", output], {
    stdin: new Blob([source]),
    stdout: "pipe",
    stderr: "pipe",
  });
  const [formatted, error, code] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
    proc.exited,
  ]);
  if (code !== 0) throw new Error(error || `bun fmt exited ${code}`);
  return formatted;
}

if (import.meta.main) {
  await writeFile(output, await buildClientSource());
  console.log(output);
}
